// report.mjs —— 账本式汇报渲染器 + tick 收尾三连。
// 两个出口：
//   render(root, seq)  —— 把第 seq 轮渲染成 Markdown 汇报。三栏顺序以 REPORT_COLUMNS
//     （schemas.mjs 唯一出处）为准；数字栏全由脚本现算自账本与档案，AI 的嘴不许碰账；
//     叙述在渲染时再过一遍叙述校验器（就算有人绕过 write 往草稿塞了坏叙述，也出不了汇报）；
//     缺任何一栏的数据当场抛错——不出残缺汇报（宪法 8）。
//   tickEnd(root, {generation, status, action}) —— 收尾三连原子执行：
//     读草稿（缺叙述/缺下轮计划就喊停，锁留在原地）→ 落 tick 正式档 → 渲染汇报并存档
//     reports/<seq>.md → 放锁 → 把 --json.status 映射成退出码交还 CLI。
// 铁律：对 .opc/ 的一切写入都经 store（有指纹有事件）；读账本（JSONL）是只读操作，
// 允许直接 fs 读。出错原样上抛，绝不吞。

import fs from 'node:fs/promises';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { EXIT, PATHS, REPORT_COLUMNS } from './schemas.mjs';
import { opcDir, readJson, writeJson, writeText } from './store.mjs';
import { readLock, release } from './lock.mjs';
import { checkNarrative } from './narrative.mjs';
import { ingest } from './ledger.mjs';

// 把 tick-end 报上来的本轮结局（--json.status）映射成退出码。
// 写法就是 EXIT 键名的小写连字符形式（ok、nothing-to-do、awaiting-approval、incident……），
// 映射直接查 EXIT 表——退出码的唯一出处是 schemas.mjs，这里一个数字都不抄。
// 别名：设计文档的返回契约把「正常干完」叫 done-work（tick 剧本也这么教），等同 ok。
const STATUS_ALIASES = { 'done-work': 'OK' };

function exitForStatus(status) {
  if (typeof status !== 'string' || status.trim() === '') {
    throw new Error('tick-end 的 --json 里必须带 status（本轮结局），例如 {"status":"done-work"}');
  }
  const trimmed = status.trim();
  const key = STATUS_ALIASES[trimmed] ?? trimmed.toUpperCase().replaceAll('-', '_');
  if (!(key in EXIT)) {
    const known = [...Object.keys(STATUS_ALIASES), ...Object.keys(EXIT).map((k) => k.toLowerCase().replaceAll('_', '-'))].join('、');
    throw new Error(`status「${status}」不在退出码表里，认得的写法：${known}`);
  }
  return EXIT[key];
}

// 起止时间算耗时：不足一秒按一秒计（汇报契约是「正整数秒」），时间倒流就是档案坏了，喊停。
function durationBetween(startIso, endIso) {
  const ms = Date.parse(endIso) - Date.parse(startIso);
  if (!Number.isFinite(ms) || ms < 0) {
    throw new Error(`起止时间不像话（起 ${startIso}，止 ${endIso}），耗时算不出来`);

// 之所以定义在 schemas.mjs 而不是 acceptance.mjs：acceptance.mjs 要 import 本文件的 WRITE_TYPES，
// 反过来引就成循环依赖了，以无环为准（同 PATHS 的理由）。
export const MACHINE_CHECK_TYPES = new Set(['file-exists', 'file-contains', 'command']);

// 退出码表：脚本对外的返回契约，带外调度器靠它判断这一轮发生了什么。
export const EXIT = {
  OK: 0,                    // 正常干完
  NOTHING_TO_DO: 10,        // 没活可干（比如全部里程碑都完成了）
  PAUSED: 11,               // 项目被人暂停，什么都不做
  INCIDENT: 12,             // 同一里程碑连败三次触发熔断，等人处理
  AWAITING_APPROVAL: 13,    // 有事等老板拍板
  PHASE1_NOT_DONE: 14,      // 阶段一还没走完（没签字），不许进阶段二干活
  STEERING_IN_PROGRESS: 15, // 调向没收尾，先把调向谈完
  LOCK_HELD: 16,            // 锁被另一个活着的会话持有
  LEDGER_GAP: 17,           // 账断了，先修账再干活
  ERROR: 20,                // 一般性出错（含数据校验不过）
  ILLEGAL_TRANSITION: 21,   // 状态机不允许的流转
  FINGERPRINT_MISMATCH: 22, // 文件指纹对不上，有人绕过脚本改了 .opc/
  MIGRATION_FAILED: 23,     // 版本迁移失败（已恢复备份）
  STALE_GENERATION: 24      // 旧代持有者想写入，被代数围栏拒绝
};

// 状态机流转表：键是当前状态，值是允许去的状态。不在表里的流转一律非法。
export const TRANSITIONS = {
  project: {
    phase1: ['phase2'],       // 阶段一签完字才许进阶段二（额外前提在状态机里查签字文件）
    phase2: ['steering'],     // 干活途中可以进调向
    steering: ['phase2']      // 调向谈完回去继续干
  },
  milestone: {
